var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 1800, H = 650;
draw.viewbox(0, 0, W, H);

var values = [null, 16, 14, 10, 8, 7, 9, 3, 2, 4, 1];
var n = 10;
var selectedIndex = 1;
var overlayMode = 'Structural order';

var treePos = {
  1: [505, 88],  2: [288, 238], 3: [725, 238],
  4: [142, 388], 5: [435, 388], 6: [582, 388], 7: [875, 388],
  8: [70, 538],  9: [218, 538], 10: [362, 538]
};
var rels = [];
for (var i = 2; i <= n; i++) rels.push([Math.floor(i / 2), i]);

var baseGray = '#d9d9d9';
var black = '#000000';
var selectedColor = '#f6b21a';
var parentColor = '#1976d2';
var childColor = '#2e7d32';
var valueColor = '#7b1fa2';

draw.rect(W, H).fill('#ffffff');

var edgeGroup = draw.group();
var nodeGroup = draw.group();
var arrayGroup = draw.group();
var arcGroup = draw.group();
var compGroup = draw.group();
var labelGroup = draw.group();

var edgeElems = {};
var arcElems = {};
var nodeCircles = {};
var nodeGroups = {};
var cellRects = {};
var cellGroups = {};
var nodeIndexLabels = {};
var arrayIndexLabels = {};
var comparisonLabels = [];

function relationKey(a, b) { return a + '-' + b; }

rels.forEach(function (r) {
  var p = r[0], c = r[1];
  var pp = treePos[p], cp = treePos[c];
  edgeElems[relationKey(p, c)] = edgeGroup.line(pp[0], pp[1], cp[0], cp[1])
    .stroke({ color: black, width: 3, linecap: 'round' });
});

function nodeTooltip(i) {
  var p = i > 1 ? Math.floor(i / 2) : null;
  var kids = [];
  if (2 * i <= n) kids.push(2 * i);
  if (2 * i + 1 <= n) kids.push(2 * i + 1);
  return 'Index ' + i + ', value ' + values[i] +
    (p ? '; parent index ' + p : '; root has no parent') +
    (kids.length ? '; children ' + kids.join(' and ') : '; no children in this heap');
}

function popupFor(i) {
  var p = i > 1 ? Math.floor(i / 2) : null;
  var left = 2 * i <= n ? 2 * i : null;
  var right = 2 * i + 1 <= n ? 2 * i + 1 : null;
  var body = 'The tree node and array cell at index ' + i + ' are the same heap item with value ' + values[i] + '. ';
  body += p ? 'Its parent is floor(' + i + '/2) = ' + p + '. ' : 'As index 1, it is the root and has no parent. ';
  body += (left || right) ? 'Its child indices are ' + (left || 'none') + ' and ' + (right || 'none') + ' from 2i and 2i+1.' : 'The indices 2i and 2i+1 are outside the array, so it is a leaf.';
  showPopup('Heap index ' + i, body);
}

function selectItem(i, withPopup) {
  selectedIndex = Math.max(1, Math.min(n, i | 0));
  var slider = document.getElementById('indexNavigatorInput');
  var out = document.getElementById('indexNavigatorVal');
  if (slider) slider.value = selectedIndex;
  if (out) out.value = selectedIndex;
  updateHighlights();
  if (withPopup) popupFor(selectedIndex);
}

function makeTreeNode(i) {
  var p = treePos[i], g = nodeGroup.group();
  nodeGroups[i] = g;
  var circle = g.circle(98).center(p[0], p[1])
    .fill(baseGray)
    .stroke({ color: black, width: 2.4 });
  nodeCircles[i] = circle;
  g.text(String(values[i]))
    .font({ family: 'Times New Roman, serif', size: 47 })
    .fill(black)
    .center(p[0], p[1] + 3);
  nodeIndexLabels[i] = labelGroup.text(String(i))
    .font({ family: 'Times New Roman, serif', size: 36 })
    .fill(black)
    .center(p[0], p[1] - 72);

  g.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(nodeTooltip(i), e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { selectItem(i, true); });
}

for (var ni = 1; ni <= n; ni++) makeTreeNode(ni);

var arrX = 1045, arrY = 342, cellW = 72, cellH = 72;

function cellCenter(i) {
  return [arrX + (i - 0.5) * cellW, arrY + cellH / 2];
}

function makeCell(i) {
  var x = arrX + (i - 1) * cellW;
  var g = arrayGroup.group();
  cellGroups[i] = g;
  cellRects[i] = g.rect(cellW, cellH)
    .move(x, arrY)
    .fill(baseGray)
    .stroke({ color: black, width: 2.2 });
  g.text(String(values[i]))
    .font({ family: 'Times New Roman, serif', size: 47 })
    .fill(black)
    .center(x + cellW / 2, arrY + cellH / 2 + 2);
  arrayIndexLabels[i] = labelGroup.text(String(i))
    .font({ family: 'Times New Roman, serif', size: 37 })
    .fill(black)
    .center(x + cellW / 2, arrY - 52);

  g.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(nodeTooltip(i), e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { selectItem(i, true); });
}

for (var ci = 1; ci <= n; ci++) makeCell(ci);

function makeArc(parent, child, above) {
  var x1 = cellCenter(parent)[0], x2 = cellCenter(child)[0];
  var y = above ? arrY : arrY + cellH;
  var d = Math.abs(child - parent);
  var cY = above ? y - (25 + 16 * d) : y + (25 + 13 * d);
  var path = 'M ' + x1 + ' ' + y + ' C ' + x1 + ' ' + cY + ', ' + x2 + ' ' + cY + ', ' + x2 + ' ' + y;
  return arcGroup.path(path).fill('none').stroke({ color: black, width: 2.2, linecap: 'round' });
}

var aboveArc = { '1-2': true, '1-3': true, '3-6': true, '3-7': true, '5-10': true };
rels.forEach(function (r) {
  arcElems[relationKey(r[0], r[1])] = makeArc(r[0], r[1], !!aboveArc[relationKey(r[0], r[1])]);
});

labelGroup.text('(a)').font({ family: 'Times New Roman, serif', size: 48 }).fill(black).center(505, 620);
labelGroup.text('(b)').font({ family: 'Times New Roman, serif', size: 48 }).fill(black).center(1405, 620);

function labelWithHalo(txt, x, y, size, color) {
  var t = compGroup.text(txt)
    .font({ family: 'Times New Roman, serif', size: size })
    .fill(color)
    .center(x, y);
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  return t;
}

function rebuildComparisons() {
  compGroup.clear();
  comparisonLabels = [];
  if (overlayMode !== 'Value order') return;

  rels.forEach(function (r) {
    var p = r[0], c = r[1];
    var pp = treePos[p], cp = treePos[c];
    var mx = (pp[0] + cp[0]) / 2;
    var my = (pp[1] + cp[1]) / 2;
    var dx = cp[0] - pp[0], dy = cp[1] - pp[1];
    var len = Math.sqrt(dx * dx + dy * dy) || 1;
    var offx = -dy / len * 18;
    var offy = dx / len * 18;
    var isSelectedRel = (p === selectedIndex || c === selectedIndex || Math.floor(selectedIndex / 2) === p && selectedIndex === c);
    var color = isSelectedRel ? valueColor : childColor;
    var label = labelWithHalo(values[p] + ' ≥ ' + values[c], mx + offx, my + offy, isSelectedRel ? 22 : 18, color);
    comparisonLabels.push(label);
  });
}

function updateHighlights() {
  var p = selectedIndex > 1 ? Math.floor(selectedIndex / 2) : null;
  var left = 2 * selectedIndex <= n ? 2 * selectedIndex : null;
  var right = 2 * selectedIndex + 1 <= n ? 2 * selectedIndex + 1 : null;
  var children = {};
  if (left) children[left] = true;
  if (right) children[right] = true;

  for (var i = 1; i <= n; i++) {
    var strokeColor = black, strokeWidth = 2.4, fillColor = baseGray;
    if (i === selectedIndex) { strokeColor = selectedColor; strokeWidth = 7; fillColor = '#f7e4a8'; }
    else if (i === p) { strokeColor = parentColor; strokeWidth = 6; fillColor = '#d8ecff'; }
    else if (children[i]) { strokeColor = childColor; strokeWidth = 6; fillColor = '#ddf0dc'; }

    nodeCircles[i].fill(fillColor).stroke({ color: strokeColor, width: strokeWidth });
    cellRects[i].fill(fillColor).stroke({ color: strokeColor, width: strokeWidth });
    if (i === selectedIndex) {
      nodeGroups[i].front();
      cellGroups[i].front();
    }
  }

  rels.forEach(function (r) {
    var a = r[0], b = r[1], key = relationKey(a, b);
    var selectedRelation = (a === selectedIndex || b === selectedIndex || (a === p && b === selectedIndex) || children[b]);
    var color = overlayMode === 'Value order' ? childColor : black;
    var width = overlayMode === 'Value order' ? 3 : 2.2;
    var opacity = overlayMode === 'Value order' ? 0.55 : 1;
    if (selectedRelation) {
      color = overlayMode === 'Value order' ? valueColor : selectedColor;
      width = 5.2;
      opacity = 1;
    }
    edgeElems[key].stroke({ color: color, width: width + 0.7, linecap: 'round' }).opacity(opacity);
    arcElems[key].stroke({ color: color, width: width, linecap: 'round' }).opacity(opacity);
  });

  rebuildComparisons();

  var info = document.getElementById('relationInfo');
  if (info) {
    var parentText = p ? 'parent = floor(' + selectedIndex + '/2) = ' + p : 'parent: none (root)';
    var childText = 'children: ' +
      (left ? '2i = ' + left : '2i outside') + ', ' +
      (right ? '2i+1 = ' + right : '2i+1 outside');
    info.textContent = 'Index ' + selectedIndex + ' has value ' + values[selectedIndex] + '; ' + parentText + '; ' + childText + '.';
  }

  labelGroup.front();
  compGroup.front();
}

function update_indexNavigator(v) {
  selectItem(v, false);
}

function toggle_overlayMode(on) {
  overlayMode = on ? 'Value order' : 'Structural order';
  var out = document.getElementById('overlayModeVal');
