  rels.forEach(function (r) {
    var p = r[0], c = r[1];
    var pp = treePos[p], cp = treePos[c];
    var mx = (pp[0] + cp[0]) / 2;
    var my = (pp[1] + cp[1]) / 2;
    var dx = cp[0] - pp[0], dy = cp[1] - pp[1];
    var len = Math.sqrt(dx * dx + dy * dy) || 1;
    var offx = -dy / len * 22;
    var offy = dx / len * 22;
    var selectedRel = (p === selectedIndex || c === selectedIndex);
    labelWithHalo(values[p] + ' ≥ ' + values[c], mx + offx, my + offy, selectedRel ? 23 : 18, selectedRel ? valueColor : childColor);
  });
}

function resetToTextbookStyle() {
  for (var i = 1; i <= n; i++) {
    nodeCircles[i].fill(baseGray).stroke({ color: black, width: 2.4 });
    cellRects[i].fill(baseGray).stroke({ color: black, width: 2.2 });
  }
  rels.forEach(function (r) {
    var key = relationKey(r[0], r[1]);
    edgeElems[key].stroke({ color: black, width: 3, linecap: 'round' }).opacity(1);
    arcElems[key].stroke({ color: black, width: 2.2, linecap: 'round' }).opacity(1);
  });
  compGroup.clear();

  var info = document.getElementById('relationInfo');
  if (info) info.textContent = 'Move the slider or click a node/cell to reveal index relationships.';

  labelGroup.front();
}

function updateHighlights() {
  if (!highlightActive) {
    resetToTextbookStyle();
    return;
  }

  var p = selectedIndex > 1 ? Math.floor(selectedIndex / 2) : null;
  var left = 2 * selectedIndex <= n ? 2 * selectedIndex : null;
  var right = 2 * selectedIndex + 1 <= n ? 2 * selectedIndex + 1 : null;
  var children = {};
  if (left) children[left] = true;
  if (right) children[right] = true;

  for (var i = 1; i <= n; i++) {
    var strokeColor = black, strokeWidth = 2.4, fillColor = baseGray;
    if (i === selectedIndex) {
      strokeColor = selectedColor;
      strokeWidth = 7;
      fillColor = selectedFill;
    } else if (i === p) {
      strokeColor = parentColor;
      strokeWidth = 6;
      fillColor = parentFill;
    } else if (children[i]) {
      strokeColor = childColor;
      strokeWidth = 6;
      fillColor = childFill;
    }

    nodeCircles[i].fill(fillColor).stroke({ color: strokeColor, width: strokeWidth });
    cellRects[i].fill(fillColor).stroke({ color: strokeColor, width: strokeWidth });
    if (i === selectedIndex) {
      nodeGroups[i].front();
      cellGroups[i].front();
    }
  }

  rels.forEach(function (r) {
    var a = r[0], b = r[1], key = relationKey(a, b);
    var selectedRelation = (b === selectedIndex) || (a === selectedIndex && children[b]);
    var color = black;
    var widthEdge = 3;
    var widthArc = 2.2;
    var opacity = 1;

    if (overlayMode === 'Value order') {
      color = childColor;
      widthEdge = 3.4;
      widthArc = 2.6;
      opacity = 0.5;
    }

    if (selectedRelation) {
      color = overlayMode === 'Value order' ? valueColor : selectedColor;
      widthEdge = 5.8;
      widthArc = 5.0;
      opacity = 1;
    }

    edgeElems[key].stroke({ color: color, width: widthEdge, linecap: 'round' }).opacity(opacity);
    arcElems[key].stroke({ color: color, width: widthArc, linecap: 'round' }).opacity(opacity);
  });

  rebuildComparisons();

  var info = document.getElementById('relationInfo');
  if (info) {
    var parentText = p ? 'parent = floor(' + selectedIndex + '/2) = ' + p : 'parent: none (root)';
    var childText = 'children: ' +
      (left ? '2i = ' + left : '2i outside') + ', ' +
      (right ? '2i+1 = ' + right : '2i+1 outside');
    info.textContent = 'Index ' + selectedIndex + ' has value ' + values[selectedIndex] + '; ' + parentText + '; ' + childText + '.';
  }

  labelGroup.front();
  compGroup.front();
}

function update_indexNavigator(v) {
  selectItem(v, false);
}

function toggle_overlayMode(on) {
  overlayMode = on ? 'Value order' : 'Structural order';
  highlightActive = true;
  var out = document.getElementById('overlayModeVal');
  if (out) out.value = overlayMode;
  updateHighlights();
}

var demoSteps = [
  {
    title: 'Two views of one heap',
    narration: 'The left panel shows the heap as a nearly complete binary tree, while the right panel stores the same nodes in array positions 1 through 10. The value sequence in the row is just the tree read level by level from left to right.',
    state: { indexNavigator: 1, overlayMode: 'Structural order', active: false }
  },
  {
    title: 'Navigate from an index',
    narration: 'Move the index slider to any cell or node. Its parent is at floor(i/2), and its children are at 2i and 2i+1 if those positions still fall inside the array.',
    state: { indexNavigator: 4, overlayMode: 'Structural order', active: true }
  },
  {
    title: 'Match tree nodes to array cells',
    narration: 'Click a node in the tree or a cell in the array to highlight the same item in both places. Its parent and children light up too, showing that the relationship is unchanged by the representation.',
    state: { indexNavigator: 5, overlayMode: 'Structural order', active: true }
  },
  {
    title: 'Separate shape from heap property',
    narration: 'Switch to the value-order overlay. The arcs still show the structure, but the emphasized comparisons now show the max-heap rule: each parent value is greater than or equal to each child value.',
    state: { indexNavigator: 2, overlayMode: 'Value order', active: true }
  }
];

var currentStep = 0;

function applyStep(k) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, k));
  var step = demoSteps[currentStep];

  selectedIndex = step.state.indexNavigator;
  highlightActive = !!step.state.active;
  overlayMode = step.state.overlayMode;

  var slider = document.getElementById('indexNavigatorInput');
  var out = document.getElementById('indexNavigatorVal');
  if (slider) slider.value = selectedIndex;
  if (out) out.value = selectedIndex;

  var modeOn = overlayMode === 'Value order';
  var toggle = document.getElementById('overlayModeInput');
  if (toggle) toggle.checked = modeOn;
  var modeOut = document.getElementById('overlayModeVal');
  if (modeOut) modeOut.value = overlayMode;

  updateHighlights();

  var narration = document.getElementById('demoNarration');
  if (narration) narration.textContent = step.narration;
  var stepLabel = document.getElementById('stepLabel');
  if (stepLabel) stepLabel.textContent = (currentStep + 1) + '/' + demoSteps.length + ' — ' + step.title;
}

function prevStep() {
  applyStep(currentStep - 1);
}

function nextStep() {
  applyStep(currentStep + 1);
}

applyStep(0);
window.__markRendered();
